\text{Câu 2. Trong không gian } Oxy, \text{ mắt một người quan sát đặt tại điểm } M(1; 2; 3) \text{ và vật cần quan sát đặt tại điểm } N(3; 6; -12). \text{ Một điểm ba cũng có dạng hình tròn tại góc tọa độ, bán kính } R = 2 \text{ thuộc mặt phẳng } (Oxy) \text{ bắt đầu xuất phát đi thẳng theo hướng vector } \vec{j} = (0;1;0) \text{ với tốc độ } v = 5 \text{ (cm/s). Tính khoảng thời gian mà trong quá trình di chuyển tâm bia đã có khúc tâm nhìn của người quan sát. làm tròn kết quả đến hàng phần trăm. (đơn vị trên mối trục tọa độ là 1 cm).}
\]

\[
\text{Câu 3. Khảo sát thời gian sử dụng điện thoại trong một ngày của mười học sinh trong lớp học có 42 học sinh thu được mẫu số liệu nhóm sau}
\]

\[
\begin{array}{|c|c|c|c|c|c|}
\hline
\text{Thời gian (phút)} & [0;20) & [20;40) & [40;60) & [60;80) & [80;100) \\
\hline
\text{Số học sinh} & 7 & a & b & 6 &  \\
\hline
\end{array}
\]

\text{Biết rằng sử dụng điện thoại trung bình của lớp trên là 40 phút. Hỏi lớp trên có nhiều bạn có thời gian sử dụng điện thoại dưới mức trung bình lớp.}

\[
\text{Câu 4. Tìm giá trị lớn nhất và nhỏ nhất của hàm số } y = (x^2 + x + 1)e^{-x} \text{ trên đoạn } [-1;0] \text{ (làm tròn đến hàng phần trăm).}
\]

\[
\text{Câu 5. Người ta bơm xăng vào bình xăng của một chiếc xe ô tô. Biết thể tích } V (lit) \text{ của xăng được bơm vào bình phụ thuộc theo thời gian } t \text{ (phút) được cho bởi công thức } V(t) = \frac{35}{4} (3t - t^2) + 4 \text{ với } 0 \leq t \leq 1. 
\]

\text{Gọi } V'(t) \text{ là tốc độ bơm của xăng vào bình. Xác định thể tích (lit) của xăng trong bình tại thời điểm mà tốc độ bơm đạt nhỏ nhất (làm tròn đến hàng phần trăm).}

\[
\text{Câu 6. Cho hình chóp } S.ABCD \text{ có đáy } ABCD \text{ là hình vuông có cạnh bằng 4. Mặt bên } SAB \text{ là tam giác đều và } SCD \text{ là tam giác vuông cạnh tại đỉnh } S. \text{ Tính thể tích khối chóp } S.ABCD \text{ (làm tròn đến hàng phần trăm).}
\]

